class Deduper:
    def __init__(self, window):
        self.window = window
        self.seen = {}  # Stores {key: last_seen_timestamp}

    def seen(self, key, timestamp):
        # Remove old entries
        # Iterate over a copy of keys to avoid RuntimeError
        for k in list(self.seen.keys()):
            if timestamp - self.seen[k] > self.window:
                del self.seen[k]

        # Check if the current key is a duplicate
        if key not in self.seen:
            self.seen[key] = timestamp
            return False

        last_seen = self.seen[key]
        # The original bug was here: >= should be >
        if timestamp - last_seen > self.window:
            self.seen[key] = timestamp
            return False
        else:
            return True

